options.css:
:root {
  --mars: #f04438;
  --lmcache: #3b82f6;
  --mooncake: #9b6cff;
  --recompute: #9ca3af;

  --text-primary: #f5f7fa;
  --text-secondary: #b6bac3;
  --text-muted: #777d88;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

.benchmark-slide {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 800px;
  height: 100%;
  overflow: hidden;
  padding: 20px 34px 18px;

  color: var(--text-primary);
  font-family: Inter, Roboto, "Helvetica Neue", Arial, sans-serif;

  background:
    radial-gradient(
      circle at 10% 38%,
      rgba(255, 255, 255, 0.035),
      transparent 36%
    ),
    linear-gradient(
      100deg,
      #292929 0%,
      #1d1d1d 31%,
      #101010 68%,
      #050505 100%
    );
}

.top-left-logo {
  position: absolute;
  top: 10px;
  left: 80px;
  z-index: 5;
  width: 120px;
  height: auto;
  object-fit: contain;
}

.bottom-left-image {
  grid-column: 1 / span 2;
  grid-row: 2;

  display: flex;
  align-items: center;
  justify-content: center;

  min-width: 0;
  min-height: 0;
  padding: 20px;
}

.bottom-left-image img {
  display: block;
  width: auto;
  height: auto;

  max-width: 320px;

  object-fit: contain;
}

.bottom-left-image,
.bottom-left-image img {
  background: transparent !important;
}

.corner-decoration {
  position: absolute;
  top: -8px;
  right: -20px;
  width: 360px;
  height: 100px;
  overflow: hidden;
  opacity: 0.55;
  pointer-events: none;
}

.corner-decoration span {
  position: absolute;
  right: 0;
  height: 14px;
  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(220, 38, 38, 0.65),
      rgba(127, 29, 29, 0.2)
    );
  transform: skewX(36deg);
  transform-origin: right center;
}

.corner-decoration span:nth-child(1) {
  top: 3px;
  width: 310px;
}

.corner-decoration span:nth-child(2) {
  top: 22px;
  width: 265px;
}

.corner-decoration span:nth-child(3) {
  top: 41px;
  width: 220px;
}

.corner-decoration span:nth-child(4) {
  top: 60px;
  width: 175px;
}

.slide-header {
  position: relative;
  z-index: 2;
  height: 82px;
}

.slide-header h1 {
  margin: 0;
  text-align: center;
  font-family: "Roboto Mono", "IBM Plex Mono", Consolas, monospace;
  font-size: clamp(29px, 3.0vw, 52px);
  font-weight: 800;
  letter-spacing: 1.5px;
  line-height: 1.15;
}

.title-accent {
  margin-right: 14px;
  color: #ef233c;
}

.title-main {
  color: transparent;
  background: linear-gradient(90deg, #ef4444, #ff8a24);
  background-clip: text;
  -webkit-background-clip: text;
}

.title-rule {
  position: absolute;
  right: -34px;
  bottom: 3px;
  left: -34px;
  height: 2px;
  background: rgba(255, 255, 255, 0.12);
}

/*
 * Two equal 5-column metric sections.
 * Summary gets 2 columns.
 */
.dashboard-layout {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-template-rows: 305px minmax(0, 1fr);
  column-gap: 28px;
  row-gap: 18px;
  height: calc(100% - 128px);
  min-height: 0;
  padding-top: 14px;
}

.summary-column {
  grid-column: 1 / span 2;
  grid-row: 1;

  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 20px;

  min-width: 0;
  padding: 12px 4px 0 8px;
}

.summary-block {
  min-width: 0;
}

.summary-label {
  margin-bottom: 4px;
  color: var(--text-primary);
  font-size: clamp(17px, 1.25vw, 24px);
  font-weight: 750;
  line-height: 1.08;
}

/*
 * Same size for both improvement percentages.
 * Reduced so the second block remains inside the top row.
 */
.summary-value,
.summary-value.small {
  color: #ff922b;
  font-size: clamp(46px, 3.9vw, 72px);
  font-weight: 400;
  letter-spacing: -3px;
  line-height: 0.94;
  white-space: nowrap;
}

.percent-symbol {
  margin-left: 3px;
  font-size: 0.5em;
  font-weight: 550;
  letter-spacing: 0;
}

.summary-detail {
  max-width: 190px;
  margin-top: 6px;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.25;
}

/*
 * Both metric columns use exactly 5 columns.
 */
.metric-column {
  grid-column: 3 / span 5;
  grid-row: 1;
  min-width: 0;
  padding-top: 8px;
}

.metric-column + .metric-column {
  grid-column: 8 / span 5;
}

.metric-column h2,
.chart-section h2 {
  margin: 0;
  color: #fff;
  font-size: clamp(21px, 1.6vw, 30px);
  font-weight: 750;
  text-align: center;
}

.metric-subtitle {
  margin-top: 4px;
  color: var(--text-secondary);
  font-size: 12px;
  text-align: center;
}

.lcd-bar-group {
  display: flex;
  flex-direction: column;
  gap: 13px;
  width: 100%;
  margin-top: 21px;
}

.lcd-row {
  display: grid;
  grid-template-columns: 138px minmax(0, 1fr) 74px;
  align-items: center;
  gap: 11px;
  width: 100%;
  min-width: 0;
}

.lcd-name {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: clamp(14px, 1vw, 19px);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lcd-name.is-mars {
  color: #fff;
  font-weight: 650;
}

.lcd-track {
  display: grid;
  grid-template-columns: repeat(30, minmax(0, 1fr));
  gap: 3px;
  width: 100%;
  min-width: 0;
  height: 32px;
}

.lcd-segment {
  height: 100%;
  border-radius: 1px;
  background: rgba(255, 255, 255, 0.065);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.025);
}

.lcd-segment.active {
  background: var(--bar-color);
  box-shadow:
    0 0 5px color-mix(in srgb, var(--bar-color), transparent 55%),
    inset 0 0 5px rgba(255, 255, 255, 0.14);
}

.lcd-value {
  color: var(--bar-color);
  font-size: clamp(14px, 1.05vw, 20px);
  text-align: right;
  white-space: nowrap;
}

.lcd-unit {
  margin-left: 3px;
  font-size: 0.62em;
}

/*
 * Both charts use equal six-column sections.
 */
.chart-section {
  grid-row: 2;
  min-width: 0;
  min-height: 0;
}

.chart-left {
  grid-column: 3 / span 5;
  grid-row: 2;
}

.chart-right {
  grid-column: 8 / span 5;
  grid-row: 2;
}

/*
 * Inner width prevents both charts from appearing excessively wide.
 * Both receive the exact same maximum width.
 */
.chart-section {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.chart-section h2 {
  width: 100%;
  margin-bottom: 8px;
}

.chart-shell {
  width: min(100%, 720px);
  height: calc(100% - 40px);
  min-height: 0;
  margin: 0 auto;
}

.live-chart {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 14px;

  width: min(100%, 720px);
  min-height: 18px;
  margin: 3px auto 0;

  color: var(--text-secondary);
  font-size: 11px;
}

.legend-entry {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch {
  width: 15px;
  height: 3px;
  border-radius: 999px;
  background: var(--legend-color);
}

.slide-footer {
  position: absolute;
  right: 34px;
  bottom: 7px;
  left: 34px;

  display: flex;
  justify-content: space-between;

  color: rgba(255, 255, 255, 0.34);
  font-size: 12px;
  letter-spacing: 0.35px;
  text-transform: uppercase;
}

@media (max-width: 1150px) {
  .benchmark-slide {
    min-height: 1100px;
    overflow: auto;
  }

  .dashboard-layout {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: auto auto auto auto;
    height: auto;
  }

  .summary-column {
    grid-column: 1 / 3;
    grid-row: 1;
    flex-direction: row;
    justify-content: space-around;
  }

  .metric-column {
    grid-column: 1;
    grid-row: 2;
  }

  .metric-column + .metric-column {
    grid-column: 2;
    grid-row: 2;
  }

  .chart-left {
    grid-column: 1 / 3;
    grid-row: 3;
  }

  .chart-right {
    grid-column: 1 / 3;
    grid-row: 4;
  }

  .chart-section {
    min-height: 360px;
  }

  .chart-shell,
  .chart-legend {
    width: min(100%, 800px);
  }
}

options.onRender:
const root = htmlNode;

const COLORS = {
  mars: "#f04438",
  lmcache: "#3b82f6",
  mooncake: "#9b6cff",
  recompute: "#9ca3af",
};

const BAR_COLORS = {
  mars: "#f04438",
  lmcache: "#9ca3af",
  mooncake: "#9ca3af",
  recompute: "#9ca3af",
};

const DISPLAY_NAMES = {
  mars: "Pooled Memory",
  lmcache: "LMCache",
  mooncake: "Mooncake",
  recompute: "Recomputation",
};

const ORDER = ["mars", "lmcache", "mooncake", "recompute"];

// Cache hit ratio excludes recompute: it has no external cache at all (a
// near-zero plateau), so it isn't meaningful next to the other three there
// -- unlike TTFT, where recompute is a real data point and stays in ORDER.
const CACHE_ORDER = ["mars", "lmcache", "mooncake"];

function valuesToArray(values) {
  if (!values) {
    return [];
  }

  if (Array.isArray(values)) {
    return values;
  }

  if (typeof values.toArray === "function") {
    return values.toArray();
  }

  if (typeof values.length === "number") {
    const output = [];

    for (let index = 0; index < values.length; index += 1) {
      output.push(
        typeof values.get === "function"
          ? values.get(index)
          : values[index]
      );
    }

    return output;
  }

  return [];
}

function finiteNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function getField(frame, type) {
  if (!frame || !Array.isArray(frame.fields)) {
    return null;
  }

  if (type === "time") {
    return (
      frame.fields.find((field) => field.type === "time") ||
      frame.fields.find((field) =>
        String(field.name || "").toLowerCase().includes("time")
      )
    );
  }

  return (
    frame.fields.find(
      (field) =>
        field.type === "number" &&
        String(field.name || "").toLowerCase() !== "time"
    ) ||
    frame.fields.find((field) => field.type === "number")
  );
}

function getSystem(frame) {
  const numericField = getField(frame, "number");

  const candidates = [
    numericField?.labels?.system,
    frame?.labels?.system,
    frame?.name,
  ];

  for (const candidate of candidates) {
    if (!candidate) {
      continue;
    }

    const normalized = String(candidate).trim().toLowerCase();

    if (ORDER.includes(normalized)) {
      return normalized;
    }

    for (const system of ORDER) {
      if (normalized.includes(system)) {
        return system;
      }
    }
  }

  return null;
}

function getRefId(frame) {
  return String(
    frame?.refId ||
      frame?.meta?.refId ||
      frame?.meta?.custom?.refId ||
      ""
  ).toUpperCase();
}

function framesForRef(refId) {
  return (data?.series || []).filter(
    (frame) => getRefId(frame) === refId.toUpperCase()
  );
}

function lastFinite(values) {
  const array = valuesToArray(values);

  for (let index = array.length - 1; index >= 0; index -= 1) {
    const value = finiteNumber(array[index]);

    if (value !== null) {
      return value;
    }
  }

  return null;
}

function seriesMap(frames) {
  const result = {};

  frames.forEach((frame) => {
    const system = getSystem(frame);
    const timeField = getField(frame, "time");
    const numberField = getField(frame, "number");

    if (!system || !numberField) {
      return;
    }

    const rawValues = valuesToArray(numberField.values);
    const rawTimes = timeField
      ? valuesToArray(timeField.values)
      : rawValues.map((_, index) => index);

    const points = [];

    for (let index = 0; index < rawValues.length; index += 1) {
      const value = finiteNumber(rawValues[index]);
      const time = finiteNumber(rawTimes[index]);

      if (value !== null && time !== null) {
        points.push({ time, value });
      }
    }

    if (points.length > 0) {
      result[system] = points;
    }
  });

  return result;
}

function latestBySystem(map, order = ORDER) {
  const result = {};

  order.forEach((system) => {
    const points = map[system] || [];

    if (points.length > 0) {
      result[system] = points[points.length - 1].value;
    }
  });

  return result;
}

function latestFromFrames(frames) {
  for (const frame of frames) {
    const numberField = getField(frame, "number");

    if (!numberField) {
      continue;
    }

    const value = lastFinite(numberField.values);

    if (value !== null) {
      return value;
    }
  }

  return null;
}

// This panel always compares Pooled Memory against a fixed competitor per
// metric (see replay_exporter.py's second_best() and cache_competitor), so
// the detail text is fixed rather than read from the second_best label like
// the other slides do.
function setImprovement(valueId, detailId, value, competitorLabel) {
  const valueNode = root.getElementById(valueId);
  const detailNode = root.getElementById(detailId);

  if (!valueNode) {
    return;
  }

  if (!Number.isFinite(value)) {
    valueNode.textContent = "--";
    return;
  }

  valueNode.textContent = (value * 100).toFixed(1);

  if (detailNode) {
    detailNode.textContent = `${DISPLAY_NAMES.mars} vs ${competitorLabel}`;
  }
}

function formatSeconds(value) {
  if (!Number.isFinite(value)) {
    return "--";
  }

  if (value < 1) {
    return value.toFixed(2);
  }

  return value.toFixed(1);
}

function formatPercent(value) {
  if (!Number.isFinite(value)) {
    return "--";
  }

  return (value * 100).toFixed(0);
}

function buildBars(containerId, currentValues, formatValue, unit, order = ORDER) {
  const container = root.getElementById(containerId);

  if (!container) {
    return;
  }

  container.replaceChildren();

  const availableValues = Object.values(currentValues).filter(Number.isFinite);

  if (availableValues.length === 0) {
    container.textContent = "Awaiting Prometheus data";
    return;
  }

  const maximum = Math.max(...availableValues) * 1.08;
  const segmentCount = 30;

  order.forEach((system) => {
    const value = currentValues[system];

    if (!Number.isFinite(value)) {
      return;
    }

    const row = document.createElement("div");
    row.className = "lcd-row";

    const name = document.createElement("div");
    name.className = `lcd-name ${system === "mars" ? "is-mars" : ""}`;
    name.textContent = DISPLAY_NAMES[system];

    const track = document.createElement("div");
    track.className = "lcd-track";
    track.style.setProperty("--bar-color", BAR_COLORS[system]);

    const activeSegments = Math.max(
      1,
      Math.round((value / maximum) * segmentCount)
    );

    for (let index = 0; index < segmentCount; index += 1) {
      const segment = document.createElement("span");

      segment.className =
        index < activeSegments
          ? "lcd-segment active"
          : "lcd-segment";

      track.appendChild(segment);
    }

    const valueNode = document.createElement("div");
    valueNode.className = "lcd-value";
    valueNode.style.setProperty("--bar-color", BAR_COLORS[system]);
    valueNode.innerHTML =
      `${formatValue(value)}<span class="lcd-unit">${unit}</span>`;

    row.append(name, track, valueNode);
    container.appendChild(row);
  });
}

function svgElement(tag, attributes = {}) {
  const node = document.createElementNS(
    "http://www.w3.org/2000/svg",
    tag
  );

  Object.entries(attributes).forEach(([key, value]) => {
    node.setAttribute(key, String(value));
  });

  return node;
}

function niceMaximum(value) {
  if (!Number.isFinite(value) || value <= 0) {
    return 1;
  }

  const exponent = Math.floor(Math.log10(value));
  const magnitude = 10 ** exponent;
  const normalized = value / magnitude;

  let rounded;

  if (normalized <= 1) {
    rounded = 1;
  } else if (normalized <= 1.5) {
    rounded = 1.5;
  } else if (normalized <= 2) {
    rounded = 2;
  } else if (normalized <= 3) {
    rounded = 3;
  } else if (normalized <= 4) {
    rounded = 4;
  } else if (normalized <= 5) {
    rounded = 5;
  } else if (normalized <= 6) {
    rounded = 6;
  } else if (normalized <= 8) {
    rounded = 8;
  } else {
    rounded = 10;
  }

  return rounded * magnitude;
}

function niceTickStep(max) {
  if (max <= 3) return 0.5;
  if (max <= 8) return 1;
  const raw = max / 6;
  const exp = Math.floor(Math.log10(raw));
  const mag = 10 ** exp;
  const norm = raw / mag;
  if (norm <= 1) return mag;
  if (norm <= 2) return 2 * mag;
  if (norm <= 5) return 5 * mag;
  return 10 * mag;
}

// isRatio switches y-axis behavior between latency-style (seconds, "nice"
// tick step search, unbounded) and ratio-style (0-1 clamp, fixed 20% step,
// percent labels) -- this panel needs both in the same file.
function buildChart(svgId, legendId, series, yAxisTitle, isRatio, order = ORDER) {
  const svg = root.getElementById(svgId);
  const legend = root.getElementById(legendId);

  if (!svg || !legend) {
    return;
  }

  svg.replaceChildren();
  legend.replaceChildren();

  // Drop any series not in `order` (e.g. recompute for the cache chart)
  // before it can influence the y-axis scale or get drawn/legended.
  const series_ = {};
  order.forEach((system) => {
    if (series[system]) {
      series_[system] = series[system];
    }
  });
  series = series_;

  const container = svg.parentElement;
  const rect = container ? container.getBoundingClientRect() : null;
  const width = rect && rect.width > 100 ? Math.round(rect.width) : 760;
  const height = rect && rect.height > 100 ? Math.round(rect.height) : 300;

  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);

  const margin = {
    top: 12,
    right: 14,
    bottom: 34,
    left: 68,
  };

  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;

  const allPoints = Object.values(series).flat();

  if (allPoints.length === 0) {
    const message = svgElement("text", {
      x: width / 2,
      y: height / 2,
      "text-anchor": "middle",
      fill: "rgba(255,255,255,0.45)",
      "font-size": 15,
    });

    message.textContent = "Awaiting Prometheus data";
    svg.appendChild(message);
    return;
  }

  const minimumTime = Math.min(
    ...allPoints.map((point) => point.time)
  );

  const maximumTime = Math.max(
    ...allPoints.map((point) => point.time)
  );

  const maximumObserved = Math.max(
    ...allPoints.map((point) => point.value)
  );

  const yMaximum = isRatio
    ? Math.min(1, niceMaximum(maximumObserved * 1.08))
    : niceMaximum(maximumObserved * 1.08);
  const timeRange = Math.max(1, maximumTime - minimumTime);

  const xScale = (time) =>
    margin.left +
    ((time - minimumTime) / timeRange) * plotWidth;

  const yScale = (value) =>
    margin.top +
    plotHeight -
    (value / yMaximum) * plotHeight;

  const defs = svgElement("defs");

  order.forEach((system) => {
    const gradient = svgElement("linearGradient", {
      id: `${svgId}-${system}-gradient`,
      x1: "0",
      y1: "0",
      x2: "0",
      y2: "1",
    });

    const topStop = svgElement("stop", {
      offset: "0%",
      "stop-color": COLORS[system],
      "stop-opacity": system === "mars" ? "0.26" : "0.08",
    });

    const bottomStop = svgElement("stop", {
      offset: "100%",
      "stop-color": COLORS[system],
      "stop-opacity": "0",
    });

    gradient.append(topStop, bottomStop);
    defs.appendChild(gradient);
  });

  svg.appendChild(defs);

  const tickStep = isRatio ? 0.2 : niceTickStep(yMaximum);

  for (let value = 0; value <= yMaximum; value = +(value + tickStep).toFixed(2)) {
    const y = yScale(value);

    const gridLine = svgElement("line", {
      x1: margin.left,
      y1: y,
      x2: width - margin.right,
      y2: y,
      stroke: "rgba(255,255,255,0.09)",
      "stroke-width": 1,
    });

    const label = svgElement("text", {
      x: margin.left - 9,
      y: y + 4,
      "text-anchor": "end",
      fill: "rgba(255,255,255,0.53)",
      "font-size": 12,
    });

    label.textContent = isRatio
      ? `${formatPercent(value)}%`
      : `${value % 1 === 0 ? value.toFixed(0) : value.toFixed(1)} s`;

    svg.append(gridLine, label);
  }

  const verticalTicks = 6;

  for (let index = 0; index <= verticalTicks; index += 1) {
    const fraction = index / verticalTicks;
    const x = margin.left + fraction * plotWidth;
    const timestamp = minimumTime + fraction * timeRange;

    const gridLine = svgElement("line", {
      x1: x,
      y1: margin.top,
      x2: x,
      y2: margin.top + plotHeight,
      stroke: "rgba(255,255,255,0.055)",
      "stroke-width": 1,
    });

    const label = svgElement("text", {
      x,
      y: height - 12,
      "text-anchor": "middle",
      fill: "rgba(255,255,255,0.48)",
      "font-size": 9,
    });

    const date = new Date(timestamp);

    label.textContent = Number.isNaN(date.getTime())
      ? ""
      : date.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        });

    svg.append(gridLine, label);
  }

  const axisTitle = svgElement("text", {
    x: 15,
    y: height / 2,
    transform: `rotate(-90 15 ${height / 2})`,
    "text-anchor": "middle",
    fill: "rgba(255,255,255,0.58)",
    "font-size": 12,
  });

  axisTitle.textContent = yAxisTitle;
  svg.appendChild(axisTitle);

  // mars drawn last (on top); everything else keeps `order`'s relative order.
  const drawingOrder = order.filter((system) => system !== "mars").concat("mars");

  drawingOrder.forEach((system) => {
    const points = series[system];

    if (!points || points.length === 0) {
      return;
    }

    const lineCoordinates = points
      .map(
        (point) =>
          `${xScale(point.time).toFixed(2)},${yScale(point.value).toFixed(2)}`
      )
      .join(" ");

    const areaCoordinates = [
      `${xScale(points[0].time)},${margin.top + plotHeight}`,
      lineCoordinates,
      `${xScale(points[points.length - 1].time)},${margin.top + plotHeight}`,
    ].join(" ");

    const area = svgElement("polygon", {
      points: areaCoordinates,
      fill: `url(#${svgId}-${system}-gradient)`,
      stroke: "none",
    });

    const line = svgElement("polyline", {
      points: lineCoordinates,
      fill: "none",
      stroke: COLORS[system],
      "stroke-width": system === "mars" ? 3.2 : 2,
      "stroke-linejoin": "round",
      "stroke-linecap": "round",
      opacity: system === "mars" ? 1 : 0.82,
    });

    svg.append(area, line);

    const samplingStep = Math.max(
      1,
      Math.ceil(points.length / 20)
    );

    points.forEach((point, index) => {
      if (
        index % samplingStep !== 0 &&
        index !== points.length - 1
      ) {
        return;
      }

      const circle = svgElement("circle", {
        cx: xScale(point.time),
        cy: yScale(point.value),
        r: system === "mars" ? 3.2 : 2.4,
        fill: COLORS[system],
        stroke: "rgba(255,255,255,0.28)",
        "stroke-width": 0.7,
      });

      svg.appendChild(circle);
    });

    const legendEntry = document.createElement("span");
    legendEntry.className = "legend-entry";

    const swatch = document.createElement("span");
    swatch.className = "legend-swatch";
    swatch.style.setProperty("--legend-color", COLORS[system]);

    const label = document.createElement("span");
    label.textContent = DISPLAY_NAMES[system];

    legendEntry.append(swatch, label);
    legend.appendChild(legendEntry);
  });
}

const ttftImprovementFrames = framesForRef("A");
const cacheImprovementFrames = framesForRef("B");

const ttftImprovement = latestFromFrames(ttftImprovementFrames);
const cacheImprovement = latestFromFrames(cacheImprovementFrames);

setImprovement(
  "ttft-improvement",
  "ttft-improvement-detail",
  ttftImprovement,
  DISPLAY_NAMES.recompute
);

setImprovement(
  "cache-improvement",
  "cache-improvement-detail",
  cacheImprovement,
  DISPLAY_NAMES.mooncake
);

const ttftSeries = seriesMap(framesForRef("C"));
const cacheSeries = seriesMap(framesForRef("D"));

buildBars("ttft-bars", latestBySystem(ttftSeries), formatSeconds, "s");
buildBars(
  "cache-bars",
  latestBySystem(cacheSeries, CACHE_ORDER),
  formatPercent,
  "%",
  CACHE_ORDER
);

buildChart(
  "ttft-chart",
  "ttft-legend",
  ttftSeries,
  "Mean TTFT (seconds)",
  false
);

buildChart(
  "cache-chart",
  "cache-legend",
  cacheSeries,
  "External prefix cache hit ratio",
  true,
  CACHE_ORDER
);

const updated = root.getElementById("last-updated");

if (updated) {
  updated.textContent =
    `Updated ${new Date().toLocaleTimeString()}`;
}

options.css:
:root {
  --mars: #f04438;
  --lmcache: #3b82f6;
  --mooncake: #9b6cff;
  --recompute: #9ca3af;

  --text-primary: #f5f7fa;
  --text-secondary: #b6bac3;
  --text-muted: #777d88;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

.benchmark-slide {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 800px;
  height: 100%;
  overflow: hidden;
  padding: 20px 34px 18px;

  color: var(--text-primary);
  font-family: Inter, Roboto, "Helvetica Neue", Arial, sans-serif;

  background:
    radial-gradient(
      circle at 10% 38%,
      rgba(255, 255, 255, 0.035),
      transparent 36%
    ),
    linear-gradient(
      100deg,
      #292929 0%,
      #1d1d1d 31%,
      #101010 68%,
      #050505 100%
    );
}

.top-left-logo {
  position: absolute;
  top: 10px;
  left: 80px;
  z-index: 5;
  width: 120px;
  height: auto;
  object-fit: contain;
}

.bottom-left-image {
  grid-column: 1 / span 2;
  grid-row: 2;

  display: flex;
  align-items: center;
  justify-content: center;

  min-width: 0;
  min-height: 0;
  padding: 20px;
}

.bottom-left-image img {
  display: block;
  width: auto;
  height: auto;

  max-width: 320px;

  object-fit: contain;
}

.bottom-left-image,
.bottom-left-image img {
  background: transparent !important;
}

.corner-decoration {
  position: absolute;
  top: -8px;
  right: -20px;
  width: 360px;
  height: 100px;
  overflow: hidden;
  opacity: 0.55;
  pointer-events: none;
}

.corner-decoration span {
  position: absolute;
  right: 0;
  height: 14px;
  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(220, 38, 38, 0.65),
      rgba(127, 29, 29, 0.2)
    );
  transform: skewX(36deg);
  transform-origin: right center;
}

.corner-decoration span:nth-child(1) {
  top: 3px;
  width: 310px;
}

.corner-decoration span:nth-child(2) {
  top: 22px;
  width: 265px;
}

.corner-decoration span:nth-child(3) {
  top: 41px;
  width: 220px;
}

.corner-decoration span:nth-child(4) {
  top: 60px;
  width: 175px;
}

.slide-header {
  position: relative;
  z-index: 2;
  height: 82px;
}

.slide-header h1 {
  margin: 0;
  text-align: center;
  font-family: "Roboto Mono", "IBM Plex Mono", Consolas, monospace;
  font-size: clamp(29px, 3.0vw, 52px);
  font-weight: 800;
  letter-spacing: 1.5px;
  line-height: 1.15;
}

.title-accent {
  margin-right: 14px;
  color: #ef233c;
}

.title-main {
  color: transparent;
  background: linear-gradient(90deg, #ef4444, #ff8a24);
  background-clip: text;
  -webkit-background-clip: text;
}

.title-rule {
  position: absolute;
  right: -34px;
  bottom: 3px;
  left: -34px;
  height: 2px;
  background: rgba(255, 255, 255, 0.12);
}

/*
 * Two equal 5-column metric sections.
 * Summary gets 2 columns.
 */
.dashboard-layout {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-template-rows: 305px minmax(0, 1fr);
  column-gap: 28px;
  row-gap: 18px;
  height: calc(100% - 128px);
  min-height: 0;
  padding-top: 14px;
}

.summary-column {
  grid-column: 1 / span 2;
  grid-row: 1;

  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 20px;

  min-width: 0;
  padding: 12px 4px 0 8px;
}

.summary-block {
  min-width: 0;
}

.summary-label {
  margin-bottom: 4px;
  color: var(--text-primary);
  font-size: clamp(17px, 1.25vw, 24px);
  font-weight: 750;
  line-height: 1.08;
}

/*
 * Same size for both improvement percentages.
 * Reduced so the second block remains inside the top row.
 */
.summary-value,
.summary-value.small {
  color: #ff922b;
  font-size: clamp(46px, 3.9vw, 72px);
  font-weight: 400;
  letter-spacing: -3px;
  line-height: 0.94;
  white-space: nowrap;
}

.percent-symbol {
  margin-left: 3px;
  font-size: 0.5em;
  font-weight: 550;
  letter-spacing: 0;
}

.summary-detail {
  max-width: 190px;
  margin-top: 6px;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.25;
}

/*
 * Both metric columns use exactly 5 columns.
 */
.metric-column {
  grid-column: 3 / span 5;
  grid-row: 1;
  min-width: 0;
  padding-top: 8px;
}

.metric-column + .metric-column {
  grid-column: 8 / span 5;
}

.metric-column h2,
.chart-section h2 {
  margin: 0;
  color: #fff;
  font-size: clamp(21px, 1.6vw, 30px);
  font-weight: 750;
  text-align: center;
}

.metric-subtitle {
  margin-top: 4px;
  color: var(--text-secondary);
  font-size: 12px;
  text-align: center;
}

.lcd-bar-group {
  display: flex;
  flex-direction: column;
  gap: 13px;
  width: 100%;
  margin-top: 21px;
}

.lcd-row {
  display: grid;
  grid-template-columns: 138px minmax(0, 1fr) 74px;
  align-items: center;
  gap: 11px;
  width: 100%;
  min-width: 0;
}

.lcd-name {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: clamp(14px, 1vw, 19px);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lcd-name.is-mars {
  color: #fff;
  font-weight: 650;
}

.lcd-track {
  display: grid;
  grid-template-columns: repeat(30, minmax(0, 1fr));
  gap: 3px;
  width: 100%;
  min-width: 0;
  height: 32px;
}

.lcd-segment {
  height: 100%;
  border-radius: 1px;
  background: rgba(255, 255, 255, 0.065);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.025);
}

.lcd-segment.active {
  background: var(--bar-color);
  box-shadow:
    0 0 5px color-mix(in srgb, var(--bar-color), transparent 55%),
    inset 0 0 5px rgba(255, 255, 255, 0.14);
}

.lcd-value {
  color: var(--bar-color);
  font-size: clamp(14px, 1.05vw, 20px);
  text-align: right;
  white-space: nowrap;
}

.lcd-unit {
  margin-left: 3px;
  font-size: 0.62em;
}

/*
 * Both charts use equal six-column sections.
 */
.chart-section {
  grid-row: 2;
  min-width: 0;
  min-height: 0;
}

.chart-left {
  grid-column: 3 / span 5;
  grid-row: 2;
}

.chart-right {
  grid-column: 8 / span 5;
  grid-row: 2;
}

/*
 * Inner width prevents both charts from appearing excessively wide.
 * Both receive the exact same maximum width.
 */
.chart-section {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.chart-section h2 {
  width: 100%;
  margin-bottom: 8px;
}

.chart-shell {
  width: min(100%, 720px);
  height: calc(100% - 40px);
  min-height: 0;
  margin: 0 auto;
}

.live-chart {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 14px;

  width: min(100%, 720px);
  min-height: 18px;
  margin: 3px auto 0;

  color: var(--text-secondary);
  font-size: 11px;
}

.legend-entry {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch {
  width: 15px;
  height: 3px;
  border-radius: 999px;
  background: var(--legend-color);
}

.slide-footer {
  position: absolute;
  right: 34px;
  bottom: 7px;
  left: 34px;

  display: flex;
  justify-content: space-between;

  color: rgba(255, 255, 255, 0.34);
  font-size: 12px;
  letter-spacing: 0.35px;
  text-transform: uppercase;
}

@media (max-width: 1150px) {
  .benchmark-slide {
    min-height: 1100px;
    overflow: auto;
  }

  .dashboard-layout {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: auto auto auto auto;
    height: auto;
  }

  .summary-column {
    grid-column: 1 / 3;
    grid-row: 1;
    flex-direction: row;
    justify-content: space-around;
  }

  .metric-column {
    grid-column: 1;
    grid-row: 2;
  }

  .metric-column + .metric-column {
    grid-column: 2;
    grid-row: 2;
  }

  .chart-left {
    grid-column: 1 / 3;
    grid-row: 3;
  }

  .chart-right {
    grid-column: 1 / 3;
    grid-row: 4;
  }

  .chart-section {
    min-height: 360px;
  }

  .chart-shell,
  .chart-legend {
    width: min(100%, 800px);
  }
}

options.onRender:
const root = htmlNode;

const COLORS = {
  mars: "#f04438",
  lmcache: "#3b82f6",
  mooncake: "#9b6cff",
  recompute: "#9ca3af",
};

const BAR_COLORS = {
  mars: "#f04438",
  lmcache: "#9ca3af",
  mooncake: "#9ca3af",
  recompute: "#9ca3af",
};

const DISPLAY_NAMES = {
  mars: "CMM-Hybrid",
  lmcache: "LMCache",
  mooncake: "Mooncake",
  recompute: "Recomputation",
};

const ORDER = ["mars", "lmcache", "mooncake", "recompute"];

function valuesToArray(values) {
  if (!values) {
    return [];
  }

  if (Array.isArray(values)) {
    return values;
  }

  if (typeof values.toArray === "function") {
    return values.toArray();
  }

  if (typeof values.length === "number") {
    const output = [];

    for (let index = 0; index < values.length; index += 1) {
      output.push(
        typeof values.get === "function"
          ? values.get(index)
          : values[index]
      );
    }

    return output;
  }

  return [];
}

function finiteNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function getField(frame, type) {
  if (!frame || !Array.isArray(frame.fields)) {
    return null;
  }

  if (type === "time") {
    return (
      frame.fields.find((field) => field.type === "time") ||
      frame.fields.find((field) =>
        String(field.name || "").toLowerCase().includes("time")
      )
    );
  }

  return (
    frame.fields.find(
      (field) =>
        field.type === "number" &&
        String(field.name || "").toLowerCase() !== "time"
    ) ||
    frame.fields.find((field) => field.type === "number")
  );
}

function getSystem(frame) {
  const numericField = getField(frame, "number");

  const candidates = [
    numericField?.labels?.system,
    frame?.labels?.system,
    frame?.name,
  ];

  for (const candidate of candidates) {
    if (!candidate) {
      continue;
    }

    const normalized = String(candidate).trim().toLowerCase();

    if (ORDER.includes(normalized)) {
      return normalized;
    }

    for (const system of ORDER) {
      if (normalized.includes(system)) {
        return system;
      }
    }
  }

  return null;
}

function getRefId(frame) {
  return String(
    frame?.refId ||
      frame?.meta?.refId ||
      frame?.meta?.custom?.refId ||
      ""
  ).toUpperCase();
}

function framesForRef(refId) {
  return (data?.series || []).filter(
    (frame) => getRefId(frame) === refId.toUpperCase()
  );
}

function lastFinite(values) {
  const array = valuesToArray(values);

  for (let index = array.length - 1; index >= 0; index -= 1) {
    const value = finiteNumber(array[index]);

    if (value !== null) {
      return value;
    }
  }

  return null;
}

function latestFromFrames(frames) {
  for (const frame of frames) {
    const numberField = getField(frame, "number");

    if (!numberField) {
      continue;
    }

    const value = lastFinite(numberField.values);

    if (value !== null) {
      return value;
    }
  }

  return null;
}

function seriesMap(frames) {
  const result = {};

  frames.forEach((frame) => {
    const system = getSystem(frame);
    const timeField = getField(frame, "time");
    const numberField = getField(frame, "number");

    if (!system || !numberField) {
      return;
    }

    const rawValues = valuesToArray(numberField.values);
    const rawTimes = timeField
      ? valuesToArray(timeField.values)
      : rawValues.map((_, index) => index);

    const points = [];

    for (let index = 0; index < rawValues.length; index += 1) {
      const value = finiteNumber(rawValues[index]);
      const time = finiteNumber(rawTimes[index]);

      if (value !== null && time !== null) {
        points.push({ time, value });
      }
    }

    if (points.length > 0) {
      result[system] = points;
    }
  });

  return result;
}

function latestBySystem(map) {
  const result = {};

  ORDER.forEach((system) => {
    const points = map[system] || [];

    if (points.length > 0) {
      result[system] = points[points.length - 1].value;
    }
  });

  return result;
}

function formatSeconds(value) {
  if (!Number.isFinite(value)) {
    return "--";
  }

  if (value < 1) {
    return value.toFixed(2);
  }

  return value.toFixed(1);
}

function setImprovement(valueId, detailId, value, frames) {
  const valueNode = root.getElementById(valueId);
  const detailNode = root.getElementById(detailId);

  if (!valueNode) {
    return;
  }

  if (!Number.isFinite(value)) {
    valueNode.textContent = "--";
    return;
  }

  valueNode.textContent = (value * 100).toFixed(1);

  const numericField = frames
    .map((frame) => getField(frame, "number"))
    .find(Boolean);

  const secondBest =
    numericField?.labels?.second_best ||
    frames[0]?.labels?.second_best;

  if (detailNode && secondBest) {
    detailNode.textContent =
      `${DISPLAY_NAMES.mars} vs ${DISPLAY_NAMES[secondBest] || secondBest}`;
  }
}

function buildBars(containerId, currentValues) {
  const container = root.getElementById(containerId);

  if (!container) {
    return;
  }

  container.replaceChildren();

  const availableValues = Object.values(currentValues).filter(Number.isFinite);

  if (availableValues.length === 0) {
    container.textContent = "Awaiting Prometheus data";
    return;
  }

  const maximum = Math.max(...availableValues) * 1.08;
  const segmentCount = 30;

  ORDER.forEach((system) => {
    const value = currentValues[system];

    if (!Number.isFinite(value)) {
      return;
    }

    const row = document.createElement("div");
    row.className = "lcd-row";

    const name = document.createElement("div");
    name.className = `lcd-name ${system === "mars" ? "is-mars" : ""}`;
    name.textContent = DISPLAY_NAMES[system];

    const track = document.createElement("div");
    track.className = "lcd-track";
    track.style.setProperty("--bar-color", BAR_COLORS[system]);

    const activeSegments = Math.max(
      1,
      Math.round((value / maximum) * segmentCount)
    );

    for (let index = 0; index < segmentCount; index += 1) {
      const segment = document.createElement("span");

      segment.className =
        index < activeSegments
          ? "lcd-segment active"
          : "lcd-segment";

      track.appendChild(segment);
    }

    const valueNode = document.createElement("div");
    valueNode.className = "lcd-value";
    valueNode.style.setProperty("--bar-color", BAR_COLORS[system]);
    valueNode.innerHTML =
      `${formatSeconds(value)}<span class="lcd-unit">s</span>`;

    row.append(name, track, valueNode);
    container.appendChild(row);
  });
}

function svgElement(tag, attributes = {}) {
  const node = document.createElementNS(
    "http://www.w3.org/2000/svg",
    tag
  );

  Object.entries(attributes).forEach(([key, value]) => {
    node.setAttribute(key, String(value));
  });

  return node;
}

function niceMaximum(value) {
  if (!Number.isFinite(value) || value <= 0) {
    return 1;
  }

  const exponent = Math.floor(Math.log10(value));
  const magnitude = 10 ** exponent;
  const normalized = value / magnitude;

  let rounded;

  if (normalized <= 1) {
    rounded = 1;
  } else if (normalized <= 1.5) {
    rounded = 1.5;
  } else if (normalized <= 2) {
    rounded = 2;
  } else if (normalized <= 3) {
    rounded = 3;
  } else if (normalized <= 4) {
    rounded = 4;
  } else if (normalized <= 5) {
    rounded = 5;
  } else if (normalized <= 6) {
    rounded = 6;
  } else if (normalized <= 8) {
    rounded = 8;
  } else {
    rounded = 10;
  }

  return rounded * magnitude;
}

function buildChart(svgId, legendId, series, yAxisTitle) {
  const svg = root.getElementById(svgId);
  const legend = root.getElementById(legendId);

  if (!svg || !legend) {
    return;
  }

  svg.replaceChildren();
  legend.replaceChildren();

  const container = svg.parentElement;
  const rect = container ? container.getBoundingClientRect() : null;
  const width = rect && rect.width > 100 ? Math.round(rect.width) : 760;
  const height = rect && rect.height > 100 ? Math.round(rect.height) : 300;

  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);

  const margin = {
    top: 12,
    right: 14,
    bottom: 34,
    left: 68,
  };

  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;

  const allPoints = Object.values(series).flat();

  if (allPoints.length === 0) {
    const message = svgElement("text", {
      x: width / 2,
      y: height / 2,
      "text-anchor": "middle",
      fill: "rgba(255,255,255,0.45)",
      "font-size": 15,
    });

    message.textContent = "Awaiting Prometheus data";
    svg.appendChild(message);
    return;
  }

  const minimumTime = Math.min(
    ...allPoints.map((point) => point.time)
  );

  const maximumTime = Math.max(
    ...allPoints.map((point) => point.time)
  );

  const maximumObserved = Math.max(
    ...allPoints.map((point) => point.value)
  );

  const yMaximum = niceMaximum(maximumObserved * 1.08);
  const timeRange = Math.max(1, maximumTime - minimumTime);

  const xScale = (time) =>
    margin.left +
    ((time - minimumTime) / timeRange) * plotWidth;

  const yScale = (value) =>
    margin.top +
    plotHeight -
    (value / yMaximum) * plotHeight;

  const defs = svgElement("defs");

  ORDER.forEach((system) => {
    const gradient = svgElement("linearGradient", {
      id: `${svgId}-${system}-gradient`,
      x1: "0",
      y1: "0",
      x2: "0",
      y2: "1",
    });

    const topStop = svgElement("stop", {
      offset: "0%",
      "stop-color": COLORS[system],
      "stop-opacity": system === "mars" ? "0.26" : "0.08",
    });

    const bottomStop = svgElement("stop", {
      offset: "100%",
      "stop-color": COLORS[system],
      "stop-opacity": "0",
    });

    gradient.append(topStop, bottomStop);
    defs.appendChild(gradient);
  });

  svg.appendChild(defs);

  function niceTickStep(max) {
    if (max <= 3) return 0.5;
    if (max <= 8) return 1;
    const raw = max / 6;
    const exp = Math.floor(Math.log10(raw));
    const mag = 10 ** exp;
    const norm = raw / mag;
    if (norm <= 1) return mag;
    if (norm <= 2) return 2 * mag;
    if (norm <= 5) return 5 * mag;
    return 10 * mag;
  }

  const tickStep = niceTickStep(yMaximum);

  for (let value = 0; value <= yMaximum; value = +(value + tickStep).toFixed(2)) {
    const y = yScale(value);

    const gridLine = svgElement("line", {
      x1: margin.left,
      y1: y,
      x2: width - margin.right,
      y2: y,
      stroke: "rgba(255,255,255,0.09)",
      "stroke-width": 1,
    });

    const label = svgElement("text", {
      x: margin.left - 9,
      y: y + 4,
      "text-anchor": "end",
      fill: "rgba(255,255,255,0.53)",
      "font-size": 12,
    });

    label.textContent = `${value % 1 === 0 ? value.toFixed(0) : value.toFixed(1)} s`;

    svg.append(gridLine, label);
  }

  const verticalTicks = 6;

  for (let index = 0; index <= verticalTicks; index += 1) {
    const fraction = index / verticalTicks;
    const x = margin.left + fraction * plotWidth;
    const timestamp = minimumTime + fraction * timeRange;

    const gridLine = svgElement("line", {
      x1: x,
      y1: margin.top,
      x2: x,
      y2: margin.top + plotHeight,
      stroke: "rgba(255,255,255,0.055)",
      "stroke-width": 1,
    });

    const label = svgElement("text", {
      x,
      y: height - 12,
      "text-anchor": "middle",
      fill: "rgba(255,255,255,0.48)",
      "font-size": 9,
    });

    const date = new Date(timestamp);

    label.textContent = Number.isNaN(date.getTime())
      ? ""
      : date.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        });

    svg.append(gridLine, label);
  }

  const axisTitle = svgElement("text", {
    x: 15,
    y: height / 2,
    transform: `rotate(-90 15 ${height / 2})`,
    "text-anchor": "middle",
    fill: "rgba(255,255,255,0.58)",
    "font-size": 12,
  });

  axisTitle.textContent = yAxisTitle;
  svg.appendChild(axisTitle);

  const drawingOrder = [
    "recompute",
    "lmcache",
    "mooncake",
    "mars",
  ];

  drawingOrder.forEach((system) => {
    const points = series[system];

    if (!points || points.length === 0) {
      return;
    }

    const lineCoordinates = points
      .map(
        (point) =>
          `${xScale(point.time).toFixed(2)},${yScale(point.value).toFixed(2)}`
      )
      .join(" ");

    const areaCoordinates = [
      `${xScale(points[0].time)},${margin.top + plotHeight}`,
      lineCoordinates,
      `${xScale(points[points.length - 1].time)},${margin.top + plotHeight}`,
    ].join(" ");

    const area = svgElement("polygon", {
      points: areaCoordinates,
      fill: `url(#${svgId}-${system}-gradient)`,
      stroke: "none",
    });

    const line = svgElement("polyline", {
      points: lineCoordinates,
      fill: "none",
      stroke: COLORS[system],
      "stroke-width": system === "mars" ? 3.2 : 2,
      "stroke-linejoin": "round",
      "stroke-linecap": "round",
      opacity: system === "mars" ? 1 : 0.82,
    });

    svg.append(area, line);

    const samplingStep = Math.max(
      1,
      Math.ceil(points.length / 20)
    );

    points.forEach((point, index) => {
      if (
        index % samplingStep !== 0 &&
        index !== points.length - 1
      ) {
        return;
      }

      const circle = svgElement("circle", {
        cx: xScale(point.time),
        cy: yScale(point.value),
        r: system === "mars" ? 3.2 : 2.4,
        fill: COLORS[system],
        stroke: "rgba(255,255,255,0.28)",
        "stroke-width": 0.7,
      });

      svg.appendChild(circle);
    });

    const legendEntry = document.createElement("span");
    legendEntry.className = "legend-entry";

    const swatch = document.createElement("span");
    swatch.className = "legend-swatch";
    swatch.style.setProperty("--legend-color", COLORS[system]);

    const label = document.createElement("span");
    label.textContent = DISPLAY_NAMES[system];

    legendEntry.append(swatch, label);
    legend.appendChild(legendEntry);
  });
}

